import java.sql.*;
import java.nio.file.*;
import java.io.*;

public class BusPassMigration{
 static final String URL=System.getenv().getOrDefault("DB_URL","jdbc:mysql://localhost:3306/assignment5"),USER=System.getenv().getOrDefault("DB_USER","root"),PASS=System.getenv().getOrDefault("DB_PASSWORD","");
 static void migrate(Connection c,Path f)throws Exception{boolean old=c.getAutoCommit();int ok=0,bad=0;c.setAutoCommit(false);try(BufferedReader r=Files.newBufferedReader(f);PreparedStatement p=c.prepareStatement("INSERT INTO bus_passes(pass_id,register_no,student_name,route_no,amount) VALUES(?,?,?,?,?)")){String line;while((line=r.readLine())!=null){try{String[]a=line.split(",",-1);if(a.length!=5)throw new IllegalArgumentException("Expected five fields");int route=Integer.parseInt(a[3]);java.math.BigDecimal amount=new java.math.BigDecimal(a[4]);if(route<0||amount.signum()<0)throw new IllegalArgumentException("Negative/invalid value");p.setString(1,a[0]);p.setString(2,a[1]);p.setString(3,a[2]);p.setInt(4,route);p.setBigDecimal(5,amount);p.addBatch();ok++;}catch(RuntimeException e){bad++;Files.writeString(Path.of("migration_failures.txt"),line+" | "+e.getMessage()+System.lineSeparator(),StandardOpenOption.CREATE,StandardOpenOption.APPEND);}}p.executeBatch();c.commit();}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(old);}System.out.println("Accepted="+ok+" rejected="+bad);}
 static void metadata(Connection c)throws SQLException{DatabaseMetaData m=c.getMetaData();System.out.println("Database: "+m.getDatabaseProductName()+" "+m.getDatabaseProductVersion());System.out.println("Driver: "+m.getDriverName()+" "+m.getDriverVersion());try(ResultSet r=m.getTables(c.getCatalog(),null,"%",new String[]{"TABLE"})){while(r.next())System.out.println("Table: "+r.getString("TABLE_NAME"));}}
 public static void main(String[]args)throws Exception{Path f=Path.of(args.length>0?args[0]:"passes.csv");try(Connection c=DriverManager.getConnection(URL,USER,PASS)){try(Statement s=c.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS bus_passes(pass_id VARCHAR(20) PRIMARY KEY,register_no VARCHAR(20),student_name VARCHAR(80),route_no INT,amount DECIMAL(10,2) NOT NULL CHECK(amount>=0))");}migrate(c,f);metadata(c);System.out.println("Decision: central MySQL for multi-campus concurrency, indexed search and transactions.");}}
}